// Context contains request data and staged response controls for pages, layouts,
// boundaries, and loading fallbacks. Do not copy a Context after first use.
// Invalid response-control inputs invalidate the staged response and produce a
// generic 500. Response controls are sealed before rendering; deferred work can
// read the request but cannot change headers, cookies, statuses, or redirects.
type Context struct {
	context.Context
	Request        *http.Request
	Params         map[string]string
	Query          url.Values
	response       responseState
	notFoundLayout bool
	parallel       *parallelState
	responseRef    *responseState
	slotParent     string
	routePool      []Route
	routeFallback  *Route
	slotTarget     *url.URL
	slotRetained   bool
	slotDefault    bool
	interceptSlot  string
	interceptFrom  string
}
type Page struct {
	Body        ui.Node
	Title       string
	Description string
	Meta        map[string]string
	Metadata    seo.Metadata
	JSONLD      []seo.StructuredData
	// Resources declares local stylesheets and font preloads for this page.
	Resources []assets.Resource
	// Stream enables progressive ui.Defer boundaries on full-document requests.
	Stream       bool
	preparedHead *renderedHead
	document     *Document
	partial      *partialResponse
}
type PageFunc func(*Context) (Page, error)
type LayoutFunc func(*Context, ui.Node) (ui.Node, error)
type ErrorFunc func(*Context, error) (Page, error)
type LoadingFunc func(*Context) (ui.Node, error)

// RegionFunc renders request-time output for a named ui.RequestRegion. The
// supplied context and request belong to this render, not the public shell
// generation. Headers are already sealed; return nested nodes for deferred work.
type RegionFunc func(*Context, json.RawMessage) (ui.Node, error)
type CachePolicy struct {
	TTL time.Duration
	// Shared selects Config.SharedCache for this explicit public-page policy.
	// Credentials, development, streaming and other privacy guards still bypass.
	Shared bool
	// Profile names a built-in or configured lifetime/browser-age policy.
	// Choose exactly one of positive TTL, Lifetime, Profile or ProfileSpec.
	Profile string
	// ProfileSpec resolves an inline partial profile against the application's
	// effective default. Choose it instead of TTL, Lifetime or a named Profile.
	ProfileSpec     *cache.ProfileSpec
	resolvedProfile *cache.Profile
	// Lifetime enables server stale-while-revalidate instead of TTL. Responses
	// stay no-store in browser/CDN caches; browser freshness is separate.
	Lifetime *cache.Lifetime
	Tags     []string
}
type Route struct {
	Pattern string
	Slots   []Slot
	// Primary is the single-owner shorthand. Primaries declares an ordered
	// outermost-first chain; choose exactly one representation.
	Primary   *PrimarySlot
	Primaries []PrimarySlot
	Page      PageFunc
	// Regions registers native request-time renderers. Map keys are stable
	// region names; boundary instance IDs are supplied by ui.RequestRegion.
	Regions map[string]RegionFunc
	// Layouts are ordered outermost first.
	Layouts     []LayoutFunc
	LayoutBases []string
	LayoutIDs   []string
	NotFound    PageFunc
	Access      []AccessBoundary
	Metadata    []MetadataLayer
	Error       ErrorFunc
	Loading     LoadingFunc
	// Prerender opts into explicit build snapshots and runtime regeneration.
	Prerender *PrerenderPolicy
	// Cache declares anonymous, request-independent request-time output.
	Cache        *CachePolicy
	API          http.HandlerFunc
	StaticParams StaticParamsFunc
	// StaticParamsID optionally shares this declaration with ancestor layers.
	StaticParamsID     string
	StaticParamsLayers []StaticParamsLayer
}
type Config struct {
	// PrerenderFS is a trusted private build artifact, separate from Assets.
	PrerenderFS fs.FS
	// PrerenderBuildMode is for the CLI build probe, never a public server.
	PrerenderBuildMode bool
	prerenderDeferred  bool
	startupContext     context.Context
	// EarlyScripts are trusted classic dependencies shared by every document.
	// They execute in parser order before the Go bootstrap.
	EarlyScripts []scripts.Script
	// Public explicitly publishes runtime settings into every browser document.
	// Values are public data. New validates and freezes this map.
	Public map[string]string
	// DevGeneration is an opaque development reload token, independent of assets.
	DevGeneration string
	// Draft verifies server-only preview sessions and bypasses shared caches.
	// Enabling a session still requires application authentication/authorization.
	Draft *draft.Manager
	// Tracing is optional server-side instrumentation. It never enters the
	// browser manifest/cache identity or records request secrets automatically.
	Tracing *telemetry.Tracer
	// Locales optionally mounts the application in negotiated language scopes.
	Locales       *LocaleConfig
	localeScope   *localeScope
	TrailingSlash bool
	BasePath      string
	AssetPrefix   string
	Routes        []Route
	NotFound      PageFunc
	Unauthorized  PageFunc
	Forbidden     PageFunc
	Assets        fs.FS
	BuildID       string
	Dev           bool
	Logger        *log.Logger
	Cache         *cache.Store
	// SharedCache stores opt-in public rendered snapshots. Its namespace must
	// be trusted for HTML and isolated from unrelated applications/writers.
	SharedCache   *shared.Store
	CacheProfiles map[string]cache.Profile
	// CacheProfileSpecs defines partial named profiles. Omitted ages inherit the
	// effective default; a name cannot also appear in CacheProfiles.
	CacheProfileSpecs map[string]cache.ProfileSpec
	Middleware        []func(http.Handler) http.Handler
	HeaderRules       []HeaderRule
	Headers           http.Header
	Handlers          map[string]http.Handler
	Actions           http.Handler
	Images            http.Handler
	Redirects         []RedirectRule
	Rewrites          []RewriteRule
	Proxy             ProxyOptions
	// Streaming bounds progressive-page rendering and deferred callbacks across
	// this application, including managed locale mounts.
	Streaming       StreamingOptions
	streamLimiter   *ui.StreamLimiter
	PreserveLayouts bool
	// ViewTransitions opts navigation into progressive native browser animation.
	// Reduced motion and unsupported browsers always use immediate DOM updates.
	ViewTransitions bool
	After           AfterOptions
}
type App struct {
	prerenderShape      string
	prerenderKnown      map[string]bool
	locales             *localeRouter
	headerRules         []compiledHeaderRule
	redirects, rewrites []compiledRule
	proxy               *rewriteProxy
	config              Config
	routes              []Route
	handler             http.Handler
	navigationJSON      string
	configurationID     string
	after               *postresponse.Scheduler
	paths               paths.Config
	assetHandler        http.Handler
	profiles            map[string]cache.Profile
	intercepts          []interceptionOwner
}

// ErrNotFound lets a loader return the application's custom 404.
var ErrNotFound = errors.New("nextgo: not found")

// NavigationProtocolVersion is the current page-envelope wire format.
const NavigationProtocolVersion = navigation.ProtocolVersion

// Document describes framework-owned HTML attributes in navigation responses.
type Document = seo.DocumentAttributes

type Envelope struct {
	// Shell identifies a negotiated public partial shell. ShellRef is only sent
	// in a stream when the caller proposes that exact cached shell generation.
	Shell         string            `json:"shell,omitempty"`
	ShellRef      bool              `json:"shellRef,omitempty"`
	Document      Document          `json:"document"`
	Version       int               `json:"version"`
	Configuration string            `json:"configuration"`
	Build         string            `json:"build"`
	URL           string            `json:"url"`
	HTML          string            `json:"html"`
	Title         string            `json:"title"`
	Description   string            `json:"description"`
	Meta          map[string]string `json:"meta"`
	Status        int               `json:"status"`
	Head          []seo.Element     `json:"head,omitempty"`
}

func validateRouteLayers(r Route) error {
	if len(r.LayoutBases) > 0 && len(r.LayoutBases) != len(r.Layouts) {
		return fmt.Errorf("route %s: layout bases do not match wrappers", r.Pattern)
	}
	for _, base := range r.LayoutBases {
		if _, err := routing.Validate(base); err != nil {
			return err
		}
		if _, ok := slotOwnerPrefix(base, r.Pattern); !ok {
			return fmt.Errorf("route %s: layout base is outside route", r.Pattern)
		}
	}
	metadataPrefix := 0
	for _, layer := range r.Metadata {
		if layer.Load == nil || layer.Layouts < metadataPrefix || layer.Layouts > len(r.Layouts) || r.API != nil {
			return fmt.Errorf("route %s: invalid metadata provider/layout prefix", r.Pattern)
		}
		metadataPrefix = layer.Layouts
	}
	previous := 0
	for _, boundary := range r.Access {
		if boundary.Layouts < previous || boundary.Layouts > len(r.Layouts) || boundary.Unauthorized == nil && boundary.Forbidden == nil {
			return fmt.Errorf("route %s: invalid access boundary layout prefix", r.Pattern)
		}
		previous = boundary.Layouts
	}
	if len(r.LayoutIDs) != 0 && len(r.LayoutIDs) != len(r.Layouts) {
		return fmt.Errorf("route %s layout IDs do not match layouts", r.Pattern)
	}
	for _, layout := range r.Layouts {
		if layout == nil {
			return fmt.Errorf("route %s: nil layout", r.Pattern)
		}
	}
	return nil
}

// New constructs an application with the default bounded startup policy.
// Use NewContext to cancel startup enumeration or shared-seed network work.
func New(c Config) (*App, error) {
	ctx := c.startupContext
	if ctx == nil {
		ctx = context.Background()
	}
	return NewContext(ctx, c)
}

// NewContext bounds construction by ctx. It is a startup context, not the
// lifetime context for later requests or completion work. Canceling construction
// can have an unknown shared import outcome; consumed build tickets never replay.
func NewContext(ctx context.Context, c Config) (*App, error) {
	if ctx == nil {
		return nil, errors.New("nextgo: startup context required")
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	c.startupContext = ctx
	app, err := newApp(c)
	if err == nil && !c.prerenderDeferred {
		// Locale children retain this context until their wrapper finishes the
		// grouped import. A ready application must not retain startup values.
		for _, scope := range app.prerenderAllScopes() {
			scope.app.config.startupContext = nil
		}
		app.config.startupContext = nil
	}
	return app, err
}

func newApp(c Config) (*App, error) {
	var earlyErr error
	c.EarlyScripts, earlyErr = freezeEarlyScripts(c.EarlyScripts)
	if earlyErr != nil {
		return nil, earlyErr
	}
	public, publicErr := publicconfig.Clone(c.Public)
	if publicErr != nil {
		return nil, publicErr
	}
	c.Public = public
	if err := initStreaming(&c); err != nil {
		return nil, err
	}
	if c.Draft != nil {
		if err := c.Draft.Validate(); err != nil {
			return nil, err
		}
	}
	if c.Locales != nil {
		return newLocaleApp(c)
	}
	if c.BuildID == "" {
		c.BuildID = "development"
	}
	switch c.BuildID {
	case "actions", "loading", "image", "events", "draft":
		return nil, fmt.Errorf("build ID %q is reserved for a framework service", c.BuildID)
	}
	if c.Logger == nil {
		c.Logger = log.Default()
	}
	pathConfig := paths.Config{BasePath: c.BasePath, AssetPrefix: c.AssetPrefix, TrailingSlash: c.TrailingSlash}
	if err := pathConfig.Validate(); err != nil {
		return nil, err
	}
	if _, err := scripts.EarlyHTML(c.EarlyScripts, pathConfig.AssetURL, ""); err != nil {
		return nil, err
	}
	a := &App{config: c, routes: append([]Route(nil), c.Routes...), paths: pathConfig}
	a.initAssetHandler()
	if err := validateSlots(a.routes); err != nil {
		return nil, err
	}
	freezeSlots(a.routes)
	if c.Cache == nil {
		c.Cache = cache.New(128, cache.WithMaxBytes(64<<20, nil))
	}
	a.config.Cache = c.Cache
	if err := a.initStaticParams(); err != nil {
		return nil, err
	}
	patterns := make([]string, 0, len(a.routes))
	for _, r := range a.routes {
		if r.StaticParams != nil && (r.API != nil || !strings.ContainsAny(r.Pattern, ":*")) {
			return nil, fmt.Errorf("route %s: StaticParams requires a dynamic page", r.Pattern)
		}
		if r.API != nil && len(r.Access) > 0 {
			return nil, fmt.Errorf("route %s: access boundaries apply only to pages; authorize HTTP handlers explicitly", r.Pattern)
		}
		if err := validateRouteLayers(r); err != nil {
			return nil, err
		}
		patterns = append(patterns, r.Pattern)
		if (r.Page == nil) == (r.API == nil) {
			return nil, fmt.Errorf("route %s must have exactly one page or API", r.Pattern)
		}
	}
	if err := routing.ValidatePatterns(patterns); err != nil {
		return nil, err
	}
	sort.SliceStable(a.routes, func(i, j int) bool {
		return routing.Less(a.routes[i].Pattern, a.routes[j].Pattern)
	})
	if err := a.initPrerenderPolicies(); err != nil {
		return nil, err
	}
	if err := a.initRequestRegions(); err != nil {
		return nil, err
	}
	if err := a.validateConfig(); err != nil {
		return nil, err
	}
	if err := a.initRules(); err != nil {
		return nil, err
	}
	if err := a.initCacheProfiles(); err != nil {
		return nil, err
	}
	if err := a.validateSharedPages(); err != nil {
		return nil, err
	}
	if err := a.initInterceptions(); err != nil {
		return nil, err
	}
	manifest := navigation.Manifest{Public: c.Public}
	manifest.Draft = c.Draft != nil
	manifest.Scripts = earlyScriptsIdentity(c.EarlyScripts)
	manifest.Prerender = a.prerenderIdentity()
	if c.localeScope != nil {
		manifest.Locale = c.localeScope.identity()
	}
	manifest.Cache = a.cachePolicyIdentity()
	manifest.Rules = a.rulesIdentity()
	manifest.Parallel = a.parallelIdentity()
	for _, rules := range [][]compiledRule{a.redirects, a.rewrites} {
		for _, rule := range rules {
			if rule.external() {
				manifest.Documents = append(manifest.Documents, rule.source)
			}
		}
	}
	for _, route := range a.routes {
		manifest.Routes = append(manifest.Routes, navigation.Route{Pattern: route.Pattern, Endpoint: route.API != nil})
	}
	for path := range a.config.Handlers {
		manifest.Handlers = append(manifest.Handlers, path)
	}
	sort.Strings(manifest.Handlers)
	manifestJSON, _ := json.Marshal(manifest)
	a.navigationJSON = string(manifestJSON)
	a.prerenderShape = navigation.ConfigurationID("prerender", a.paths, manifest, a.config.PreserveLayouts, a.config.ViewTransitions)
	a.configurationID = navigation.ConfigurationID(a.config.BuildID, a.paths, manifest, a.config.PreserveLayouts, a.config.ViewTransitions)
	a.handler = http.HandlerFunc(a.serveHTTP)
	for i := len(c.Middleware) - 1; i >= 0; i-- {
		if c.Middleware[i] == nil {
			return nil, fmt.Errorf("nil middleware")
		}
		a.handler = c.Middleware[i](a.handler)
	}
	a.handler = httpx.Compression(a.handler)
	if err := a.initPrerenderRuntime(); err != nil {
		return nil, err
	}
	if err := c.startupContext.Err(); err != nil {
		return nil, err
	}
	var err error
	a.after, err = postresponse.New(c.After, c.Logger.Printf)
	if err != nil {
		return nil, err
	}
	return a, nil
}

func segments(p string) []string {
	if p == "/" {
		return nil
	}
	// Remove only the root separator. Empty segments are significant: trimming
	// every slash would make //about or /about// match a different route.
	return strings.Split(strings.TrimPrefix(p, "/"), "/")
}

// Shape validates a generated pattern and identifies parameter-name collisions.
func Shape(p string) (string, error) { return routing.Validate(p) }

func match(pattern, path string) (map[string]string, bool) {
	return routing.Match(pattern, path)

}

func (a *App) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if a.config.Tracing != nil {
		a.config.Tracing.ServeHTTP(w, r, a.serveRequest)
		return
	}
	a.serveRequest(w, r)
}
func (a *App) serveRequest(w http.ResponseWriter, r *http.Request) {
	if a.locales != nil {
		a.locales.serveHTTP(w, r)
		return
	}
	// An explicit alternate asset prefix is a public asset-only mount.
	if prefix := a.paths.AssetPath(); prefix != a.paths.BasePath || (a.paths.AssetPrefix != "" && !strings.HasPrefix(a.paths.AssetPrefix, "/")) {
		if local, ok := localRequest(r, prefix); ok && assetRequest(local) {
			a.assetHandler.ServeHTTP(w, local)
			return
		}
	}
	r = r.WithContext(context.WithValue(r.Context(), publicContextKey{}, a.config.Public))
	original := r
	if a.config.localeScope != nil {
		telemetry.SetLocale(r.Context(), a.config.localeScope.code)
		r = r.WithContext(context.WithValue(r.Context(), localeContextKey{}, a.config.localeScope))
		w.Header().Set("Content-Language", a.config.localeScope.code)
	}
	r, cancel := withRequestURI(r)
	defer cancel()
	if a.config.Draft != nil {
		r = a.config.Draft.BindRequest(r)
	}
	r = r.WithContext(paths.WithContext(r.Context(), a.paths))
	local, ok := localRequest(r, a.paths.BasePath)
	if !ok {
		http.NotFound(w, original)
		return
	}
	r = a.logicalRequest(local)
	if draft.Enabled(r.Context()) {
		w = privateDraftWriter(w)
	}
	r = r.WithContext(context.WithValue(r.Context(), cacheProfileContextKey{}, a.profiles))
	r = r.WithContext(context.WithValue(r.Context(), pageCacheScopeKey{}, a))
	afterCtx, afterScope := a.after.Request(r.Context())
	r = r.WithContext(afterCtx)
	defer afterScope.Finish()
	for key, values := range a.config.Headers {
		w.Header()[key] = append([]string(nil), values...)
	}
	w.Header().Set("X-Content-Type-Options", "nosniff")
	if w.Header().Get("Referrer-Policy") == "" {
		w.Header().Set("Referrer-Policy", "strict-origin-when-cross-origin")
	}
	var headerOK bool
	w, r, headerOK = a.bindHeaderRules(w, r)
	if !headerOK {
		return
	}
	a.handler.ServeHTTP(w, r)
}
func (a *App) serveHTTP(w http.ResponseWriter, r *http.Request) {
	if a.config.PrerenderBuildMode && r.Context().Value(prerenderCaptureKey{}) == nil {
		http.Error(w, "build probe cannot serve public requests", 503)
		return
	}
	if scripts.Nonce(r.Context()) != "" {
		r = r.WithContext(cache.WithBypass(r.Context()))
	}
	if a.ruleSensitive(r) {
		r = r.WithContext(context.WithValue(r.Context(), sensitiveRuleKey{}, true))
	}
	if a.serveConfigured(w, r) {
		return
	}
	if a.serveAssets(w, r) {
		return
	}
	if a.redirectCanonical(w, r) {
		return
	}
	if a.applyRewrites(w, r) {
		return
	}
	for _, route := range a.routes {
		params, ok := match(route.Pattern, r.URL.EscapedPath())
		if !ok {
			continue
		}
		telemetry.SetRoute(r.Context(), route.Pattern)
		if route.API != nil {
			for k, v := range params {
				r.SetPathValue(k, v)
			}
			telemetry.Handle(w, r, telemetry.Info{Name: "nextgo.api", Route: route.Pattern}, route.API)
			return
		}
		if r.Method != "GET" && r.Method != "HEAD" {
			w.Header().Set("Allow", "GET, HEAD")
			w.WriteHeader(405)
			return
		}
		interception, interceptErr := a.selectInterception(r)
		if interceptErr != nil {
			a.config.Logger.Printf("interception: %v", interceptErr)
			r = r.WithContext(context.WithValue(r.Context(), parallelRequestKey{}, true))
			w.Header().Set("Cache-Control", "private, no-store")
			a.respond(w, r, errorPage(), 500)
			return
		}
		// A target's navigation response depends on the active background. It
		// must not enter public or URL-only speculative caches, even outside it.
		if r.Header.Get("X-Nextgo-Navigate") == "1" && a.interceptionTarget(r.URL) {
			route.Cache = nil
		}
		request := r
		if interception != nil {
			route = interception.route
			params, _ = match(route.Pattern, interception.url.EscapedPath())
			request = r.Clone(r.Context())
			request.URL = interception.url
		}
		if len(route.Slots) > 0 || hasPrimaries(route) {
			r = r.WithContext(context.WithValue(r.Context(), parallelRequestKey{}, true))
		}
		request = request.WithContext(r.Context())
		ctx := &Context{Context: r.Context(), Request: request, Params: params, Query: request.URL.Query()}
		if len(route.Regions) > 0 {
			bound := ui.WithRegionResolver(r.Context(), a.requestRegionResolver(ctx, route))
			r = r.WithContext(bound)
			ctx.Context = bound
			ctx.Request = request.WithContext(bound)
		}
		if interception != nil {
			ctx.slotTarget = r.URL
			ctx.interceptSlot = interception.slot
		}
		page, status := a.load(ctx, route, w)
		var redirected bool
		var responseErr error
		status, redirected, responseErr = a.applyResponse(w, r, ctx, status)
		if responseErr != nil {
			a.config.Logger.Printf("response controls: %v", responseErr)
			page = errorPage()
		}
		if redirected {
			return
		}
		a.respond(w, r, page, status)
		return
	}
	if r.Method != "GET" && r.Method != "HEAD" {
		w.WriteHeader(404)
		return
	}
	ctx := &Context{Context: r.Context(), Request: r, Params: map[string]string{}, Query: r.URL.Query()}
	page, status := a.notFound(ctx)
	status, redirected, responseErr := a.applyResponse(w, r, ctx, status)
	if responseErr != nil {
		a.config.Logger.Printf("response controls: %v", responseErr)
		page = errorPage()
	}
	if redirected {
		return
	}
	a.respond(w, r, page, status)
}

func (a *App) render(c *Context, r Route) (page Page, status int) {
	status = 200
	defer func() {
		if v := recover(); v != nil {
			a.config.Logger.Printf("page panic: %v", v)
			page, status = a.renderError(c, r, fmt.Errorf("render panic: %v", v))
		}
	}()
	if err := a.beginParallel(c, r); err != nil {
		return errorPage(), 400
	}
	c, r = a.selectPrimary(c, r)
	page, err := r.Page(c)
	if accessStatus(err) != 0 {
		c.disablePrimaryRetention()
		return a.renderAccess(c, r, err)
	}
	if errors.Is(err, ErrNotFound) {
		c.disablePrimaryRetention()
		return a.renderRouteNotFound(c, r)
	}
	if err == nil {
		page.Body, err = a.wrapLayouts(c, r, page.Body)
	}
	if err == nil {
		page, err = a.resolveMetadata(c, r, page)
	}
	if accessStatus(err) != 0 {
		c.disablePrimaryRetention()
		return a.renderAccess(c, r, err)
	}
	if errors.Is(err, ErrNotFound) {
		c.disablePrimaryRetention()
		return a.renderRouteNotFound(c, r)
	}
	if err != nil {
		a.config.Logger.Printf("render %s: %v", c.Request.URL.Path, err)
		return a.renderError(c, r, err)
	}
	if c.parallel != nil && c.parallel.status > status {
		status = c.parallel.status
	}
	return page, status
}
func (a *App) renderRouteNotFound(c *Context, r Route) (Page, int) {
	if r.NotFound != nil {
		p, e := r.NotFound(c)
		if e != nil {
			if accessStatus(e) != 0 {
				return a.renderAccess(c, r, e)
			}
			return a.renderError(c, r, e)
		}
		p.Body, e = a.wrapLayouts(c, r, p.Body)
		if e != nil {
			if accessStatus(e) != 0 {
				return a.renderAccess(c, r, e)
			}
			return a.renderError(c, r, e)
		}
		return p, 404
	}
	return a.notFound(c)
}
func (a *App) wrapLayouts(c *Context, r Route, body ui.Node) (ui.Node, error) {
	return a.wrapLayoutPrefix(c, r, body, len(r.Layouts))
}
func (a *App) wrapLayoutPrefix(c *Context, r Route, body ui.Node, prefix int) (ui.Node, error) {
	for i := prefix - 1; i >= 0; i-- {
		layoutContext := c
		if c.parallel != nil {
			layoutContext = c.parallel.layoutContext(i)
			var err error
			body, err = c.primaryNodeAt(i, body)
			if err != nil {
				return nil, err
			}
		}
		id := ""
		if (a.config.PreserveLayouts || len(r.LayoutBases) > 0) && len(r.LayoutIDs) == len(r.Layouts) {
			id = r.LayoutIDs[i]
			body = ui.El("nextgo-outlet", ui.Attrs{"data-nextgo-outlet": id}, body)
		}
		var err error
		func() {
			if c.parallel != nil {
				previous := c.parallel.owner
				c.parallel.owner = i
				defer func() { c.parallel.owner = previous }()
			}
			body, err = r.Layouts[i](layoutContext, body)
		}()
		if err != nil {
			return nil, &layoutError{index: i, cause: err}
		}
		if id != "" {
			attrs := ui.Attrs{"data-nextgo-layout": id}
			if !c.parallel.primaryAt(i) && len(r.LayoutBases) == len(r.Layouts) {
				selection, e := layoutContext.primarySelection(i)
				if e != nil {
					return nil, e
				}
				raw, e := selectionJSON(selection)
				if e != nil {
					return nil, e
				}
				attrs["data-nextgo-selection"] = raw
			}
			body = ui.El("nextgo-layout", attrs, body)
		}
	}
	return body, nil
}
func (a *App) renderError(c *Context, r Route, cause error) (page Page, status int) {
	c.disablePrimaryRetention()
	defer func() {
		if p := recover(); p != nil {
			a.config.Logger.Printf("error boundary panic: %v", p)
			page, status = errorPage(), 500
		}
	}()
	if r.Error != nil {
		page, err := r.Error(c, cause)
		if err == nil {
			body, e := a.wrapLayouts(c, r, page.Body)
			if e == nil {
				page.Body = body
				return page, 500
			}
			err = e
		}
		if accessStatus(err) != 0 {
			return a.renderAccess(c, r, err)
		}
		a.config.Logger.Printf("error boundary failed: %v", err)
	}
	return errorPage(), 500
}
func (a *App) notFound(c *Context) (page Page, status int) {
	defer func() {
		if v := recover(); v != nil {
			a.config.Logger.Printf("404 panic: %v", v)
			page, status = errorPage(), 500
		}
	}()
	if a.config.NotFound != nil {
		previous := c.notFoundLayout
		c.notFoundLayout = true
		defer func() { c.notFoundLayout = previous }()
		p, err := a.config.NotFound(c)
		if err == nil {
			return p, 404
		}
		if accessStatus(err) != 0 {
			return a.renderAccess(c, Route{}, err)
		}
		a.config.Logger.Printf("404: %v", err)
		return errorPage(), 500
	}
	return Page{Title: "Not found", Body: ui.El("h1", nil, ui.Text("Page not found"))}, 404
}
func errorPage() Page {
	return Page{Title: "Server error", Body: ui.El("h1", nil, ui.Text("Something went wrong"))}
}

func (a *App) respond(w http.ResponseWriter, r *http.Request, p Page, status int) {
	telemetry.Handle(w, r, telemetry.Info{Name: "nextgo.render"}, func(w http.ResponseWriter, r *http.Request) { a.respondPage(w, r, p, status) })
}
func (a *App) respondPage(w http.ResponseWriter, r *http.Request, p Page, status int) {
	a.draftResponse(w, r)
	if flag, _ := r.Context().Value(parallelRequestKey{}).(bool); flag || ruleSensitive(r.Context()) {
		w.Header().Set("Cache-Control", "private, no-store")
		clearNavigationReuse(w.Header())
	}
	p = a.localeMetadata(p)
	if status == http.StatusUnauthorized || status == http.StatusForbidden {
		w.Header().Set("Cache-Control", "private, no-store")
		w.Header().Set("X-Robots-Tag", "noindex")
		clearNavigationReuse(w.Header())
		p.Stream = false
		p.Metadata.Robots = "noindex"
		meta := make(map[string]string, len(p.Meta))
		for key, value := range p.Meta {
			if !strings.EqualFold(key, "robots") {
				meta[key] = value
			}
		}
		p.Meta = meta
		p.preparedHead = nil
	}
	var metadataErr error
	p, metadataErr = normalizePageMetadata(p)
	if metadataErr != nil {
		a.config.Logger.Printf("metadata: %v", metadataErr)
		p = a.localeMetadata(errorPage())
		status = 500
	}
	if p.Title == "" {
		p.Title = p.Metadata.Title
	}
	if p.Description == "" {
		p.Description = p.Metadata.Description
	}
	documentAttrs, documentErr := pageDocument(p)
	head, headHTML, headErr := pageHeadPaths(p, a.paths)
	if headErr != nil || documentErr != nil {
		a.config.Logger.Printf("head: %v", headErr)
		p = a.localeMetadata(errorPage())
		head = nil
		headHTML = ""
		status = 500
		documentAttrs, _ = seo.ResolveDocument(p.Metadata)
	}
	if a.config.localeScope != nil {
		w.Header().Set("Content-Language", documentAttrs.Language)
	}
	if p.Stream && status == 200 && r.Header.Get("X-Nextgo-Navigate") == "1" && r.Header.Get(navigation.PurposeHeader) == "prefetch" {
		w.Header().Set("Cache-Control", "private, no-store")
		clearNavigationReuse(w.Header())
		w.Header().Set(navigation.ConfigurationHeader, a.configurationID)
		w.Header().Set(navigation.ProtocolHeader, fmt.Sprint(navigation.ProtocolVersion))
		w.Header().Add("Vary", "X-Nextgo-Navigate, X-Nextgo-Stream, X-Nextgo-Purpose")
		w.WriteHeader(204)
		return
	}
	if p.Stream && status == http.StatusOK {
		ctx, cancel := context.WithTimeout(r.Context(), a.config.Streaming.Timeout)
		defer cancel()
		work, release, err := a.config.streamLimiter.Begin(ctx)
		if err != nil {
			if !errors.Is(err, ui.ErrStreamCapacity) {
				a.config.Logger.Printf("stream admission: %v", err)
				a.respondPage(w, r, errorPage(), http.StatusInternalServerError)
				return
			}
			w.Header().Set("Retry-After", "1")
			w.Header().Set(navigation.StreamAdmissionHeader, "busy")
			a.respondPage(w, r, streamBusyPage(), http.StatusServiceUnavailable)
			return
		}
		defer release()
		r = r.WithContext(work)
	}
	if p.Stream && status == 200 && r.Method == "GET" && r.Header.Get("X-Nextgo-Navigate") == "1" && r.Header.Get(navigation.StreamHeader) == fmt.Sprint(navigation.StreamVersion) {
		a.respondNavigationStream(w, r, p, head, documentAttrs)
		return
	}
	if p.Stream && status == 200 && r.Header.Get("X-Nextgo-Navigate") != "1" && r.Method != "HEAD" {
		a.respondStream(w, r, p, headHTML, documentAttrs)
		return
	}
	body, err := ui.HTMLContext(r.Context(), p.Body)
	if err != nil {
		a.config.Logger.Printf("HTML: %v", err)
		p = a.localeMetadata(errorPage())
		head = nil
		headHTML = ""
		body, _ = ui.HTML(p.Body)
		documentAttrs, _ = seo.ResolveDocument(p.Metadata)
		status = 500
	}
	w.Header().Set(navigation.ConfigurationHeader, a.configurationID)
	w.Header().Add("Vary", "X-Nextgo-Navigate, X-Nextgo-Stream, X-Nextgo-Purpose")
	if status != 200 || w.Header().Get("Cache-Control") == "" {
		if len(w.Header().Values("Set-Cookie")) > 0 || status == http.StatusUnauthorized || status == http.StatusForbidden || status == http.StatusServiceUnavailable {
			w.Header().Set("Cache-Control", "private, no-store")
		} else {
			w.Header().Set("Cache-Control", "no-store")
		}
		clearNavigationReuse(w.Header())
	}
	nonceResponse(w, r)
	w.Header().Set("X-Content-Type-Options", "nosniff")
	if status == http.StatusNoContent || status == http.StatusResetContent || status == http.StatusNotModified {
		w.WriteHeader(status)
		return
	}
	if r.Header.Get("X-Nextgo-Navigate") == "1" {
		w.Header().Set(navigation.ProtocolHeader, fmt.Sprint(NavigationProtocolVersion))
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		shell, shellRef := partialEnvelopeFields(r, p, status, false)
		envelope := Envelope{
			Shell: shell, ShellRef: shellRef,
			Version: NavigationProtocolVersion, Configuration: a.configurationID, Document: documentAttrs,
			Build: a.config.BuildID, URL: requestURI(r), HTML: body,
			Title: p.Title, Description: p.Description, Meta: p.Meta, Status: status, Head: head,
		}
		if shell != "" {
			encoded, err := json.Marshal(envelope)
			if err != nil || len(encoded) > navigation.MaxStreamFrame {
				// Public UI may be valid yet exceed speculative transport bounds.
				// Skip speculation without running any private request regions.
				clearNavigationReuse(w.Header())
				w.Header().Del(navigation.ShellProtocolHeader)
				w.WriteHeader(http.StatusNoContent)
				return
			}
			w.Header().Set(navigation.ShellProtocolHeader, fmt.Sprint(navigation.ShellVersion))
			w.Header().Set("X-Nextgo-Prefetch", "shell")
			w.Header().Set(navigation.ShellStaleHeader, fmt.Sprint(shellRetentionMillis(w.Header(), p.partial.reuseUntil)))
			w.WriteHeader(status)
			if r.Method != "HEAD" {
				_, _ = w.Write(encoded)
			}
			return
		}
		w.WriteHeader(status)
		if r.Method != "HEAD" {
			_ = json.NewEncoder(w).Encode(envelope)
		}
		return
	}
	var buf bytes.Buffer
	err = document.Execute(&buf, struct {
		Page          Page
		Document      Document
		Body          template.HTML
		Build         string
		Dev           bool
		DevGeneration string
		Head          template.HTML
		Preserve      bool
		Transitions   bool
		Navigation    string
		Configuration string
		Draft         string
		Paths         paths.Config
		Runtime       string
		Style         string
		Nonce         string
		Early         template.HTML
	}{p, documentAttrs, template.HTML(body), a.config.BuildID, a.config.Dev, a.config.DevGeneration, template.HTML(nonceHead(headHTML, scripts.Nonce(r.Context()))), a.config.PreserveLayouts, a.config.ViewTransitions, a.navigationJSON, a.configurationID, a.draftState(r), a.paths, a.paths.RuntimeURL(a.config.BuildID), mustPath(a.paths.AssetURL("/style.css")), scripts.Nonce(r.Context()), template.HTML(a.earlyScripts(r))})
	if err != nil {
		http.Error(w, "Unable to render document", 500)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	if r.Method != "HEAD" {
		_, _ = w.Write(buf.Bytes())
	}
}

var document = template.Must(template.New("document").Parse(`<!doctype html>
<html lang="{{.Document.Language}}" dir="{{.Document.Direction}}"><head><meta charset="utf-8"><meta name="viewport" content="{{.Document.Viewport}}">
<title>{{.Page.Title}}</title><meta name="description" content="{{.Page.Description}}">
{{range $name,$value := .Page.Meta}}<meta data-nextgo-meta name="{{$name}}" content="{{$value}}">{{end}}
{{.Head}}
<style{{if .Nonce}} nonce="{{.Nonce}}"{{end}}>` + frameworkCSS + `</style>
<link rel="stylesheet" href="{{.Style}}">
{{.Early}}
<script{{if .Nonce}} nonce="{{.Nonce}}"{{end}} src="{{.Runtime}}wasm_exec.js"></script><script data-nextgo-bootstrap=""{{if .Nonce}} nonce="{{.Nonce}}"{{end}} async src="{{.Runtime}}boot.js"></script>
</head><body{{if .Draft}} data-nextgo-draft="{{.Draft}}"{{end}} data-nextgo-configuration="{{.Configuration}}" data-nextgo-basepath="{{.Paths.BasePath}}" data-nextgo-assets="{{.Paths.AssetPrefix}}" data-nextgo-runtime="{{.Runtime}}"{{if .Paths.TrailingSlash}} data-nextgo-trailing-slash="true"{{end}} data-nextgo-navigation="{{.Navigation}}" data-nextgo-build="{{.Build}}"{{if .Dev}} data-nextgo-dev="true" data-nextgo-dev-generation="{{.DevGeneration}}"{{end}}{{if .Preserve}} data-nextgo-preserve-layouts="true"{{end}}{{if .Transitions}} data-nextgo-transitions="true"{{end}}>
<div id="nextgo-status" role="status" aria-live="polite" hidden></div>
` + routeAnnouncer + `
<div id="nextgo-app" tabindex="-1">{{.Body}}</div>
<span id="nextgo-initial-ready" hidden></span>
<noscript>Interactive controls require JavaScript and WebAssembly. Page links still work.</noscript>
</body></html>`))
